import type { ImageMetadata } from 'astro';

/**
 * Every photo on the site, by id. Files are src/assets/photos/<id>.jpg, generated by
 * scripts/gen-photos.mjs and picked by eye (no lettering, no logos, no misspelled brand).
 * Alt text describes what is in the frame, never claims an event ("our repair of…").
 */
const files = import.meta.glob<{ default: ImageMetadata }>('../assets/photos/*.jpg', { eager: true });

export const photoAlt = {
  'home-hero': 'Technician kneeling on a drop cloth in front of a stainless French door refrigerator with the freezer drawer open',
  'arrival-01': 'Plain white service van with open rear doors parked in front of a stucco house on a Southern California street',
  'evaporator-01': 'Freezer with the rear panel removed, the evaporator coil buried in a block of frost',
  'defrost-01': 'Multimeter probes on the defrost heater under a cleared evaporator coil',
  'icemaker-01': 'Ice maker assembly crusted with frost being slid out of the ice compartment in a French door refrigerator',
  'icemaker-02': 'Frosted old ice maker next to a new ice maker assembly on a drop cloth',
  'compressor-01': 'Multimeter probes on the compressor connector behind a refrigerator with the rear access cover removed',
  'board-01': 'Refrigerator main control board with relays and harness connectors held in two hands',
  'fan-01': 'Evaporator fan motor removed from an open freezer',
  'gasket-01': 'New magnetic door gasket being pressed into a refrigerator door',
  'leak-01': 'Puddle of water on a tile floor in front of a refrigerator freezer drawer',
  'drain-01': 'Warm water flushed into the defrost drain under a freezer evaporator coil',
  'parts-01': 'Parts organizer with a fan motor, defrost heater, sensor and water valve on a drop cloth in front of a refrigerator',
  'family-hub-01': 'Four-door French door refrigerator with a large touchscreen on the right door',
  'bespoke-01': 'Four-door refrigerator with sage green glass upper doors and white lower drawers built into cabinets',
  'french-door-01': 'Stainless French door refrigerator with a middle drawer, bottom freezer and door dispenser',
  'side-by-side-01': 'Stainless side-by-side refrigerator with an ice and water dispenser in a kitchen alcove',
  'top-freezer-01': 'Stainless top-freezer refrigerator in an apartment kitchen',
} as const;

export type PhotoId = keyof typeof photoAlt;

export function photo(id: PhotoId): { src: ImageMetadata; alt: string } {
  const f = files[`../assets/photos/${id}.jpg`];
  if (!f) throw new Error(`photo ${id}: no file at src/assets/photos/${id}.jpg`);
  return { src: f.default, alt: photoAlt[id] };
}
